def calculate_ticket_metrics(df):
    row_indices = df.index.tolist()
    target_cols = [df.columns[0] if i % 2 == 0 else df.columns[1] for i in range(len(row_indices))]
    selected_values = df.lookup(row_indices, target_cols)
    results = np.array(selected_values).astype(float)
    return np.mean(results)

